  "items": [
    {
      "id": "R1",
      "type": "CAUSE",
      "otherName": "",
      "reason": "실시간 매매의 어려움이 환금성을 낮추는 실제 작용을 설명하므로 인과 관계이다."
    },
    {
      "id": "R2",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "일반 펀드의 낮은 환금성이라는 한계를 보완하는 상품으로 ETF가 실제 도입되므로 문제·대응 관계이다."
    },
    {
      "id": "R3",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "투자자가 자유롭게 거래하도록 하기 위해 펀드를 거래소에 상장하는 구조를 마련했으므로 수단·목적 관계이다."
    },
    {
      "id": "R4",
      "type": "CAUSE",
      "otherName": "",
      "reason": "기초 지수를 추종하는 설계가 지수 구성 주식을 비율대로 보유하는 것과 유사한 경제적 효과를 발생시키므로 인과 관계이다."
    },
    {
      "id": "R5",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "ETF 한 주로 지수 구성 주식 전체를 보유하는 것과 유사한 효과를 얻는다는 사실에서 소액 분산 투자가 가능하다는 판단을 도출한다."
    },
    {
      "id": "R6",
      "type": "CAUSE",
      "otherName": "",
      "reason": "개별 주식처럼 자유롭게 매매할 수 있는 거래 구조가 높은 환금성으로 이어지므로 인과 관계이다."
    },
    {
      "id": "R7",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "장 마감 후 하루 한 번 산출되는 지표의 장중 활용 한계를 실시간 추정 순자산가치의 제공으로 보완한다."
    },
    {
      "id": "R8",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "ETF가 장중 실시간으로 거래된다는 사실을 근거로 실시간 참고 지표를 제공하는 이유를 설명한다."
    },
    {
      "id": "R9",
      "type": "CAUSE",
      "otherName": "",
      "reason": "투자자의 매수·매도 수요에 따른 가격 형성이 자산 가치와 시장 가격 사이의 괴리를 발생시킬 수 있으므로 인과 관계이다."
    },
    {
      "id": "R10",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "시장 가격과 실시간 추정 순자산가치 사이의 괴리를 장중 괴리율이라는 지표와 계산식으로 나타낸다."
    },
    {
      "id": "R11",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "자산 가치보다 현저히 비싸거나 싸게 거래된다는 사실에서 본질 가치와 동떨어진 거래의 위험이 크다는 판단을 도출한다."
    },
    {
      "id": "R12",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "가격 괴리에 따른 거래 위험에 대응하여 괴리율을 축소하는 유동성 공급자의 차익 거래가 제시된다."
    },
    {
      "id": "R13",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "투자자의 원활한 ETF 거래를 돕기 위해 매수·매도 호가를 지속적으로 제시하므로 수단·목적 관계이다."
    },
    {
      "id": "R14",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "설정과 환매는 자산 운용사에 제공하는 대상과 지급받는 대상이 서로 반대이므로 같은 기준에서 절차를 대조한다."
    },
    {
      "id": "R15",
      "type": "PROCESS",
      "otherName": "",
      "reason": "설정으로 발행받은 ETF 증권을 바탕으로 다음 단계인 시장 매도가 진행되므로 과정·순서 관계이다."
    },
    {
      "id": "R16",
      "type": "PROCESS",
      "otherName": "",
      "reason": "환매로 지급받은 기초 자산 바스켓을 다음 단계에서 시장에 매도하므로 과정·순서 관계이다."
    },
    {
      "id": "R17",
      "type": "CONDITION",
      "otherName": "",
      "reason": "괴리율이 양수인지 음수인지에 따라 설정 후 ETF 매도와 환매 후 바스켓 매도로 거래 방식이 갈린다."
    },
    {
      "id": "R18",
      "type": "CAUSE",
      "otherName": "",
      "reason": "유동성 공급자의 반복적인 차익 거래가 시장 가격과 본질 가치 사이의 괴리를 실제로 축소하므로 인과 관계이다."
    },
    {
      "id": "R19",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "기초 지수 추종이라는 일반적 특성을 추종 정도와 수익 목표가 다른 패시브형·액티브형의 세부 설명으로 구체화한다."
    },
    {
      "id": "R20",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "패시브형과 액티브형은 상관 계수 기준과 추구하는 수익 목표가 다르므로 두 상품 유형을 대조한다."
    },
    {
      "id": "R21",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "기초 지수의 수익률을 유사하게 구현하려는 목적을 위해 상관 계수를 0.9 이상으로 유지하도록 설계한다."
    },
    {
      "id": "R22",
      "type": "MEANS_END",
      "otherName": "",
      "reason": "초과 수익을 얻으려는 목적을 위해 전문가의 판단에 따른 종목 운용을 수단으로 삼는다."
    },
    {
      "id": "R23",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "수익률을 확대해 추종하는 레버리지 구조에 손실 폭도 확대될 수 있다는 동일 상품의 위험과 한계를 덧붙인다."
    },
    {
      "id": "R24",
      "type": "CAUSE",
      "otherName": "",
      "reason": "매일 달라진 평가액을 새 원금으로 삼아 배율을 적용하는 구조가 지수 회복 후에도 원금 손실을 발생시키는 작용을 설명한다."
    },
    {
      "id": "R25",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "지수가 회복해도 평가액이 9,000원에 그치는 수치 사례가 레버리지형의 원금 미회복 위험이라는 일반적 성질을 구체적으로 보여 준다."
    },
    {
      "id": "R26",
      "type": "PROCESS",
      "otherName": "",
      "reason": "하락일에 산출된 평가액 6,000원을 바탕으로 다음 날 상승률을 적용하는 단계가 이어지므로 과정·순서 관계이다."
    },
    {
      "id": "R27",
      "type": "CAUSE",
      "otherName": "",
      "reason": "주가 상승 전에 증권을 살 권리를 판매한 것이 이후 가격 상승에 따른 수익 실현을 제한하므로 인과 관계이다."
    },
    {
      "id": "R28",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "하나의 커버드콜형 ETF 안에서 상승 수익의 제한이라는 단점과 주기적 현금 수익이라는 장점이 함께 제시된다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "증권 보유와 권리 판매를 결합한 운용 전략이 상승 수익의 제한과 주기적 현금 수익 확보라는 결과를 낳는다."
    },
    {
      "id": "R30",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "유형마다 수익 목표와 운용 기준이 다르다는 사실이 상품 선택 시 운용 방식 등을 종합적으로 고려해야 한다는 당위의 근거가 된다."
    },
    {
      "id": "R31",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "특수 수익 구조마다 장점과 위험이 다르다는 사실을 근거로 수익률 외에 원금 손실과 고유 위험까지 고려해야 한다는 결론을 세운다."
    }
  ]
}

